    async def stream_chapter1258(self):
        yield "1 Ti-mô-thê  6 : 1 - 21"

        yield (
            "6 Những người ở dưới ách nô lệ hãy tiếp tục xem chủ của mình là đáng "
            "được kính trọng hết lòng, hầu cho danh Đức Chúa Trời và sự dạy dỗ của "
            "ngài không bao giờ bị nói phạm. 2 Ngoài ra, những ai có chủ là người tin "
            "đạo thì đừng vì cớ họ là anh em mình mà thiếu tôn trọng họ. Thay vì thế, "
            "hãy sẵn lòng phục vụ họ hơn nữa, vì những người được mình phục vụ chu "
            "đáo chính là anh em đồng đạo yêu dấu của mình."
        )

        yield (
            "Hãy tiếp tục dạy dỗ và khuyên bảo dựa trên những điều ta nói với con. "
            "3 Nếu ai dạy một giáo lý khác và không đồng ý với sự dạy dỗ hữu ích* đến "
            "từ Chúa Giê-su Ki-tô chúng ta, cũng chẳng tán thành sự dạy dỗ phù hợp "
            "với lòng sùng kính 4 thì đó là kẻ lên mặt kiêu ngạo và không hiểu gì cả. "
            "Người ấy ham* cãi vã và tranh luận về từ ngữ. Những điều ấy gây nên sự "
            "đố kỵ, xung đột, vu khống,* nghi kỵ xấu xa, 5 khiến những người có tâm "
            "trí bại hoại và không còn biết chân lý là gì thường xuyên tranh cãi về "
            "những vấn đề nhỏ nhặt, nghĩ rằng lòng sùng kính là phương tiện để được "
            "lợi. 6 Quả thật, lòng sùng kính cùng với sự thỏa lòng* mang lại lợi ích "
            "lớn lao. 7 Vì khi ra đời, chúng ta chẳng mang gì theo, và khi qua đời "
            "cũng chẳng mang gì đi được. 8 Vậy nên, có thức ăn, áo mặc* thì phải thỏa "
            "lòng."
        )

        yield (
            "9 Còn những ai quyết chí làm giàu thì rơi vào cám dỗ, cạm bẫy cùng nhiều "
            "ước muốn vô nghĩa tai hại, nhấn chìm người ta trong sự hủy hoại và diệt "
            "vong. 10 Bởi lòng ham tiền là gốc rễ của mọi loại tai hại, vì nuôi dưỡng "
            "ham muốn đó mà một số người đã bị lạc khỏi đức tin và tự gây cho mình* "
            "nhiều nỗi đau."
        )

        yield (
            "11 Tuy nhiên, hỡi con, là người của Đức Chúa Trời, hãy tránh* khỏi những "
            "điều ấy. Nhưng hãy theo đuổi sự công chính, lòng sùng kính, đức tin, "
            "tình yêu thương, tính chịu đựng và mềm mại. 12 Hãy vì đức tin mà tranh "
            "đấu trong trận chiến tốt lành; hãy nắm chắc sự sống vĩnh cửu mà con đã "
            "được gọi đến và đã công bố trước mặt nhiều người làm chứng."
        )

        yield (
            "13 Trước mặt Đức Chúa Trời, đấng giữ cho mọi vật được sống, cùng Đấng "
            "Ki-tô Giê-su, đấng đã công khai làm chứng trước mặt Bôn-xơ Phi-lát, ta "
            "dặn con 14 phải vâng giữ các điều răn sao cho không tì vết và không chỗ "
            "trách được, cho đến khi Chúa Giê-su Ki-tô chúng ta được tỏ lộ. 15 Vào "
            "thời điểm ấn định cho sự tỏ lộ ấy, Đấng Quyền Lực, là đấng hạnh phúc và "
            "duy nhất, sẽ tỏ mình ra. Ngài là Vua của những người làm vua, Chúa của "
            "những người làm chúa, 16 là đấng duy nhất có sự bất tử, ngự trong ánh "
            "sáng không thể đến gần, và chưa ai từng thấy hoặc có thể thấy ngài. "
            "Nguyện ngài được tôn kính và có quyền năng muôn đời. A-men."
        )

        yield (
            "17 Hãy khuyên bảo* những người giàu có trong thế gian* này đừng ngạo "
            "mạn, đừng đặt hy vọng nơi sự giàu sang không chắc chắn mà hãy đặt hy "
            "vọng nơi Đức Chúa Trời, đấng cung cấp dồi dào mọi thứ mà chúng ta vui "
            "hưởng. 18 Hãy bảo họ làm điều lành, giàu có trong việc tốt, rộng rãi, "
            "sẵn sàng chia sẻ, 19 tích trữ cho mình một kho báu an toàn, là nền tảng "
            "tốt cho tương lai, hầu nắm chắc sự sống thật."
        )

        yield (
            "20 Hỡi Ti-mô-thê, hãy gìn giữ những gì đã được giao phó cho con, hãy "
            "tránh khỏi những lời sáo rỗng phạm đến điều thánh, và tránh những mâu "
            "thuẫn của điều mà người ta sai lầm gọi là “sự hiểu biết”. 21 Vì phô "
            "trương sự hiểu biết đó mà một số người đã bị lạc khỏi đức tin."
        )

        yield "Nguyện lòng nhân từ bao la của Đức Chúa Trời ở cùng anh em."

        yield "^ 1 Ti 6:3 Hay “lành mạnh”."

