class Thong_diep_cua_Kinh_Thanh_Worker:
    """
    [Thông điệp của Kinh Thánh]
    Service Pipeline Worker | State: ACTIVE
    """

    async def stream_thong_diep_cua_kinh_thanh(self):
        yield "B1"

        yield (
            "Giê-hô-va Đức Chúa Trời có quyền cai trị. Cách cai trị của ngài là ưu "
            "việt. Ý định của ngài đối với trái đất và nhân loại sẽ được hoàn thành."
        )

        yield "Sau 4026 TCN"

        yield (
            "“Con rắn” nêu nghi vấn về quyền cai trị và cách cai trị của Đức Giê-hô- "
            "va. Đức Giê-hô-va hứa sẽ dấy lên một “dòng dõi” sau này giày đạp con "
            "rắn, tức Sa-tan (Sáng thế 3:1-5, 15). Tuy nhiên, Đức Giê-hô-va cho con "
            "người thời gian để tự cai trị dưới ảnh hưởng của con rắn."
        )

        yield "1943 TCN"

        yield (
            "Đức Giê-hô-va nói với Áp-ra-ham rằng “dòng dõi” được hứa trước sẽ là một "
            "trong những con cháu của ông.—Sáng thế 22:18."
        )

        yield "Sau 1070 TCN"

        yield (
            "Đức Giê-hô-va đoan chắc với vua Đa-vít và sau này với con trai ông là "
            "Sa-lô-môn rằng “dòng dõi” được hứa trước sẽ ra từ dòng tộc của họ.—2 Sa- "
            "mu-ên 7:12, 16; 1 Các vua 9:3-5; Ê-sai 9:6, 7."
        )

        yield "29 CN"

        yield (
            "Đức Giê-hô-va xác nhận Chúa Giê-su là “dòng dõi” được hứa trước và là "
            "đấng kế vị ngôi vua Đa-vít.—Ga-la-ti 3:16; Lu-ca 1:31-33; 3:21, 22."
        )

        yield "33 CN"

        yield (
            "Con rắn, tức Sa-tan, làm cho “dòng dõi” tạm thời bị thương qua việc "
            "khiến Chúa Giê-su bị giết. Đức Giê-hô-va làm cho Chúa Giê-su sống lại để "
            "lên trời và chấp nhận giá trị mạng sống hoàn hảo của Chúa Giê-su, qua đó "
            "cung cấp cơ sở để tha tội và ban sự sống vĩnh cửu cho con cháu "
            "A-đam.—Sáng thế 3:15; Công vụ 2:32-36; 1 Cô-rinh-tô 15:21, 22."
        )

        yield "Khoảng 1914 CN"

        yield (
            "Chúa Giê-su quăng con rắn, tức Sa-tan, xuống trái đất và hắn bị hạn chế "
            "tại đó trong một thời gian ngắn.—Khải huyền 12:7-9, 12."
        )

        yield "Tương lai"

        yield (
            "Chúa Giê-su giam cầm Sa-tan trong 1.000 năm và sau đó hủy diệt, tức giày "
            "đạp đầu hắn theo nghĩa tượng trưng. Ý định ban đầu của Đức Giê-hô-va đối "
            "với trái đất và nhân loại được hoàn thành, danh ngài không còn bị sỉ "
            "nhục và đường lối cai trị của ngài được biện minh.—Khải huyền 20:1-3, "
            "10; 21:3, 4."
        )

